    defer s.mu.Unlock()
    ck := C.CString(key)
    defer C.free(unsafe.Pointer(ck))
    var found C.int
    val := C.kv_get(s.cstore, ck, &found)
    if found == 0 {
        return "", false, nil
    }
    goVal := C.GoString(val)
    C.kv_free_value(val)
